output:
520	                    pts[i + 1].lon, pts[i + 1].lat);
521	            }
522	            hint = coarse;
523	            start = hint > VMAP_NAV_MATCH_ACQUIRE_HALF
524	                ? hint - VMAP_NAV_MATCH_ACQUIRE_HALF : 0u;
525	            end = hint + VMAP_NAV_MATCH_ACQUIRE_HALF;
526	            if (end > last_seg) {
527	                end = last_seg;
528	            }
529	            acc = coarse_acc;
530	        } else {
531	            start = hint > VMAP_NAV_MATCH_BACK_SEGS
532	                ? hint - VMAP_NAV_MATCH_BACK_SEGS : 0u;
533	            end = hint + VMAP_NAV_MATCH_AHEAD_SEGS;
534	            if (end + 1u >= n) {
535	                end = n - 2u;
536	            }
537	            acc = nav->track_seg_start_m;
538	        }
539	
540	        for (uint32_t i = hint; i > start; i--) {
541	            acc -= vmap_geo_haversine_m(pts[i - 1u].lon, pts[i - 1u].lat,
542	                pts[i].lon, pts[i].lat);
543	        }
544	
545	        for (uint32_t i = start; i <= end; i++) {
546	            double tloc = 0.0;
547	            const double d = vmap_geo_point_to_seg_m(lon, lat,
548	                pts[i].lon, pts[i].lat, pts[i + 1].lon, pts[i + 1].lat, &tloc);
549	            const double seg_m = vmap_geo_haversine_m(pts[i].lon, pts[i].lat,
550	                pts[i + 1].lon, pts[i + 1].lat);
551	            const double candidate_along = acc + seg_m * tloc;
552	            double score = d;
553	
554	            if (continuity) {
555	                const double delta = candidate_along - prev_along;
556	                double excess = 0.0;
557	
558	                if (delta < -VMAP_NAV_MATCH_BACK_TOL_M) {
559	                    excess = -delta - VMAP_NAV_MATCH_BACK_TOL_M;
560	                } else if (delta > VMAP_NAV_MATCH_AHEAD_TOL_M) {
561	                    excess = delta - VMAP_NAV_MATCH_AHEAD_TOL_M;
562	                }
563	                score += fmin(VMAP_NAV_MATCH_MAX_PENALTY,
564	                    excess * VMAP_NAV_MATCH_PROGRESS_W);
565	            }
566	
567	            if (score < best_score) {
568	                best_score = score;
569	                best_d = d;
570	                seg = i;
571	                best_seg_start_m = acc;
572	                best_t = tloc;
573	                best_along = candidate_along;
574	            }
575	            acc += seg_m;
576	        }
577	
578	        nav->track_seg_hint = seg;
579	        nav->track_seg_start_m = best_seg_start_m;
580	        nav->track_hint_valid = true;
581	        off_m = best_d;
582	        vmap_route_set_progress_match(nav->route, lon, lat, seg, best_t);
583	        along = vmap_route_effective_along_m(nav->route, best_along);
584	    }
585	    total = vmap_route_total_length_m(nav->route);
586	
587	    nav->state.active = true;
588	    nav->state.off_route_m = off_m;
589	    nav->state.along_m = along;
590	    nav->state.remain_m = fmax(0.0, total - along);
591	
592	    /* 每拍把骑行者位置同步给 route：绘制用它把"已走过的那段"刷灰。
593	     * **放在 nav 更新内部**，这样不管 UI 从哪条路径喂位置都生效
594	     * （之前挂在某一条 UI 路径上，实际走的不是那条 → 走过的线还是蓝的）。 */
595	    vmap_route_set_progress_pos(nav->route, lon, lat);
596	
597	    if (nav->state.remain_m <= VMAP_ROUTE_ARRIVE_M) {
598	        nav->state.arrived = true;
599	    }
600	
601	    /* 终点常常**不在路上**：它会被吸到最近的路网节点（实测偏 171 m），骑行轨迹从旁边
602	     * 过去（屏上"偏航 43 m"），于是沿路剩余距离永远 > 45 m，**永远不判到达、导航不收尾**
603	     * （用户现场：骑过终点还在导）。这里补一条：离**路线末点**足够近也算到达 —— 用直线
604	     * 距离，不看沿路剩余。半径取 VMAP_NAV_ARRIVE_NEAR_M 的 1/4（默认 75 m）。 */
605	    {
606	        const uint32_t rn = vmap_route_point_count(nav->route);
607	        const vmap_route_pt_t * rp = vmap_route_points(nav->route);
608	
609	        if (rp != NULL && rn >= 2u
610	            && vmap_geo_haversine_m(lon, lat, rp[rn - 1u].lon,
611	                   rp[rn - 1u].lat) <= (VMAP_NAV_ARRIVE_NEAR_M * 0.25)) {
612	            nav->state.arrived = true;
613	        }
614	    }
615	
616	    if (speed_kph > 3.0f) {
617	        nav->state.eta_s = (float)(nav->state.remain_m / ((double)speed_kph / 3.6));
618	    } else {
619	        nav->state.eta_s = 0.0f;
620	    }
621	
622	    nav_update_passed_maneuvers(nav, along);
623	    nav_update_deviation(nav, lon, lat, course_deg, speed_kph, off_m, seg);
624	    nav_update_next_maneuver(nav, along, nav->state.remain_m);
625	}
