1317	 * @brief vmap route set progress pos。
1318	 */
1319	void vmap_route_set_progress_match(vmap_route_t * route, double lon, double lat,
1320	    uint32_t seg, double seg_t)
1321	{
1322	    if (!route || !vmap_route_is_active(route)
1323	        || seg + 1u >= route->pt_count) {
1324	        return;
1325	    }
1326	
1327	    if (seg_t < 0.0) {
1328	        seg_t = 0.0;
1329	    } else if (seg_t > 1.0) {
1330	        seg_t = 1.0;
1331	    }
1332	
1333	    route->anchor_lon = lon;
1334	    route->anchor_lat = lat;
1335	    route->progress_seg = seg;
1336	    route->progress_lon = route->pts[seg].lon
1337	        + (route->pts[seg + 1u].lon - route->pts[seg].lon) * seg_t;
1338	    route->progress_lat = route->pts[seg].lat
1339	        + (route->pts[seg + 1u].lat - route->pts[seg].lat) * seg_t;
1340	    route->progress_valid = true;
1341	}
