1349	    double best_t = 0.0;
1350	    double best_d = 1e18;
1351	
1352	    if (!route || !vmap_route_is_active(route)) {
1353	        return;
1354	    }
1355	
1356	    route->progress_pos_seen = true;
1357	
1358	    pts = route->pts;
1359	    n = route->pt_count;
1360	    start = route->progress_valid && route->progress_seg > 1u
1361	        ? route->progress_seg - 1u : 0u;
1362	
1363	    for (uint32_t i = start; i + 1u < n; i++) {
1364	        double t = 0.0;
1365	        const double d = vmap_geo_point_to_seg_m(lon, lat,
1366	            pts[i].lon, pts[i].lat, pts[i + 1u].lon, pts[i + 1u].lat, &t);
1367	
1368	        if (d < best_d) {
1369	            best_d = d;
1370	            best_seg = i;
1371	            best_t = t;
1372	        }
1373	    }
1374	
1375	    vmap_route_set_progress_match(route, lon, lat, best_seg, best_t);
