101	/*
102	 * 屏幕**实际重绘**帧率统计（诊断用，默认不打印）。
103	 *
104	 * 取 LVGL 的 LV_EVENT_RENDER_START / RENDER_READY：`refr_invalid_areas()` 在
105	 * `inv_p == 0` 时直接返回，所以这对事件只包住"真的画了东西"的那一段（含所有
106	 * 条带与 flush），不会把空转的 16 ms 刷新节拍算进来。
107	 *
108	 * 为什么不用 LV_EVENT_REFR_START/READY：那一对在无脏区时也会发，fps 恒等于
109	 * 刷新定时器频率，没有意义。
110	 *
111	 * 打印级别是 LOG_DEBUG ⇒ 默认静默；要看时 `ctl log all`（看完 `ctl log notice`）。
112	 */
113	static struct {
114	    uint32_t t0;
115	    uint32_t n;
116	    uint32_t sum;
117	    uint32_t max;
118	    uint32_t win;
119	    /* 整次刷新（REFR_START..REFR_READY）与其中"画"的部分（RENDER_*）分开记：
120	     * 两者之差 = layout/失效合并/任务派发/flush 等待，是刷新管线的固定开销。 */
121	    uint32_t refr_t0;
122	    uint32_t refr_sum;
123	    uint32_t refr_n;
124	} s_fps;
125	static bool s_fps_hooked;
126	
127	static void vmap_fps_probe_cb(lv_event_t * e)
128	{
129	    const lv_event_code_t code = lv_event_get_code(e);
130	    uint32_t now = lv_tick_get();
131	    uint32_t dt;
132	    uint32_t win;
133	
134	    if (code == LV_EVENT_REFR_START) {
135	        s_fps.refr_t0 = now;
136	        return;
137	    }
138	    if (code == LV_EVENT_REFR_READY) {
139	        s_fps.refr_sum += lv_tick_elaps(s_fps.refr_t0);
140	        s_fps.refr_n++;
141	        return;
142	    }
143	    if (code == LV_EVENT_RENDER_START) {
144	        s_fps.t0 = now;
145	        return;
146	    }
147	    if (code != LV_EVENT_RENDER_READY) {
148	        return;
149	    }
150	
151	    dt = lv_tick_elaps(s_fps.t0);
152	    if (s_fps.win == 0u) {
153	        s_fps.win = now;
154	    }
155	    s_fps.n++;
156	    s_fps.sum += dt;
157	    if (dt > s_fps.max) {
158	        s_fps.max = dt;
159	    }
160	
161	    win = lv_tick_elaps(s_fps.win);
162	    if (win < 2000u) {
163	        return;
164	    }
165	    if (s_fps.n > 0u) {
166	        /* fps 用 x10 定点：n * 10000 / win。refr=整次刷新，ovh=刷新管线开销。 */
167	        const uint32_t refr = (s_fps.refr_n > 0u) ? (s_fps.refr_sum / s_fps.refr_n) : 0u;
168	        const uint32_t draw = s_fps.sum / s_fps.n;
169	
170	        syslog(LOG_DEBUG,
171	            "[mapfps] n=%u fps=%u.%u avg=%ums max=%ums refr=%ums ovh=%ums win=%ums",
172	            (unsigned)s_fps.n,
173	            (unsigned)(s_fps.n * 10000u / win / 10u),
174	            (unsigned)(s_fps.n * 10000u / win % 10u),
175	            (unsigned)draw,
176	            (unsigned)s_fps.max,
177	            (unsigned)refr,
178	            (unsigned)((refr > draw) ? (refr - draw) : 0u),
179	            (unsigned)win);
180	    }
181	    s_fps.n = 0u;
182	    s_fps.sum = 0u;
183	    s_fps.max = 0u;
184	    s_fps.refr_sum = 0u;
185	    s_fps.refr_n = 0u;
186	    s_fps.win = now;
187	}
